"""Legacy-compatible batch job error-handling runner."""

from typing import Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], None]) -> list[dict]:
    """Run scheduled jobs sequentially and return an attempt log."""
    run_log: list[dict] = []

    for job in jobs:
        policy_info = job["on_error"]
        policy = policy_info["policy"]
        retries = policy_info.get("retries", 0)

        attempts = 0
        succeeded = False

        max_attempts = retries + 1 if policy == "RETRY" else 1
        for _ in range(max_attempts):
            attempts += 1
            try:
                executor(job)
            except Exception:
                continue
            else:
                succeeded = True
                break

        if succeeded:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "ok",
                    "audits": [],
                }
            )
            continue

        if policy == "CONTINUE":
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "skip",
                    "audits": ["BATCH_ROWSKIP"],
                }
            )
            continue

        run_log.append(
            {
                "name": job["name"],
                "attempts": attempts,
                "outcome": "abort",
                "audits": [],
            }
        )
        break

    return run_log
